var n=`0421-stegt-fl-sk`;var i=`world-0421`;var o=`DK`;var l=`northern-europe`;var a=4;var r=61;var s={en:`Stegt Flæsk`,ua:`Смажена свиняча грудинка`};var u={en:`A traditional dish from Denmark, centered on pork belly, potato, all-purpose flour, whole cow milk. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Данія. Основні складники: свиняча грудинка, картопля, пшеничне борошно універсальне, цільне коров'яче молоко. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Roast in a preheated 190°C oven for about 26 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 26 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:26,i:[[`pork-belly`,750,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,650,`g`],[`water`,1e3,`ml`]]},{en:`Melt the fat, stir in flour and cook gently for about 7 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 7 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:7,i:[[`unsalted-butter`,50,`g`],[`all-purpose-flour`,40,`g`],[`whole-cow-milk`,330,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var g={slug:n,id:i,country:`DK`,region:l,servings:4,minutes:61,title:s,text:u,steps:d};export{o as country,g as default,i as id,r as minutes,l as region,a as servings,n as slug,d as steps,u as text,s as title};